code.source:
#include <iostream>
using namespace std;

int add(int a, int b) {
    return a + b;
}

int main() {
    int total = add(4, 9);
    cout << "Total: " << total << endl;
    return 0;
}

#include <iostream>
using namespace std;

int bigger(int a, int b) {
    if (a > b) {
        return a;
    }
    return b;
}

int main() {
    cout << bigger(7, 12) << endl;
    cout << bigger(30, 5) << endl;
    return 0;
}

